def comps(g,val=3):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and not seen[i][j]:
                st=[(i,j)]; c=[]
                while st:
                    r,c_=st.pop()
                    if seen[r][c_]: continue
                    seen[r][c_]=True; c.append((r,c_))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<H and 0<=cc<W and g[rr][cc]==val and not seen[rr][cc]: st.append((rr,cc))
                out.append(c)
    return out
