def comps(g,vset):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] in vset and not seen[i][j]:
                st=deque([(i,j)]); cell=set()
                while st:
                    a,b=st.popleft()
                    if (a,b) in cell: continue
                    cell.add((a,b)); seen[a][b]=True
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=a+dr,b+dc
                        if 0<=rr<H and 0<=cc<W and g[rr][cc] in vset and (rr,cc) not in cell: st.append((rr,cc))
                out.append(cell)
    return out
