def comps2(g,val):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and not seen[i][j]:
                st=deque([(i,j)]); cell=set()
                while st:
                    r,c=st.popleft()
                    if (r,c) in cell: continue
                    cell.add((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<H and 0<=cc<W and g[rr][cc]==val and (rr,cc) not in cell: st.append((rr,cc))
                out.append(cell)
    return out
