def comps_m(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] in (3,9) and not seen[i][j]:
                st=deque([(i,j)]); cell=set()
                while st:
                    r,c=st.popleft()
                    if (r,c) in cell: continue
                    cell.add((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<H and 0<=cc<W and g[rr][cc] in (3,9) and (rr,cc) not in cell: st.append((rr,cc))
                out.append(cell)
    return out
def f(g):
    H,W=len(g),len(g[0]); out=[r[:] for r in g]; rm=set()
    for cell in comps_m(g):
        if any(v==9 for v in [g[r][c] for r,c in cell]):
            rm|=cell
    for r,c in rm: out[r][c]=0
