def f(g):
    Hh,Ww=len(g),len(g[0]); out=[row[:] for row in g]
    for i in range(Hh):
        for j in range(Ww):
            if g[i][j]!=3: continue
            st=deque([(i,j)]); cell=set()
            while st:
                r,c=st.popleft()
                if (r,c) in cell: continue
                cell.add((r,c))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    rr,cc=r+dr,c+dc
                    if 0<=rr<Hh and 0<=cc<Ww and g[rr][cc]==3 and (rr,cc) not in cell: st.append((rr,cc))
            # count 9s in 8-neighborhood of the component
            cnt=0
            for r,c in cell:
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<Hh and 0<=cc<Ww and g[rr][cc]==9: cnt+=1
            if cnt<=1:
                for r,c in cell: out[r][c]=0
    return out
