def ncomps(g,val):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and not seen[i][j]:
                st=deque([(i,j)]); cell=set(); seen[i][j]=True
                while st:
                    r,c=st.popleft()
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<H and 0<=cc<W and g[rr][cc]==val and not seen[rr][cc]:
                            seen[rr][cc]=True; st.append((rr,cc)); cell.add((rr,cc))
                out.append(cell)
    return out
